WITH fixes(pos,why) AS (VALUES (5,'Correto. Pelo art. 12, I, b, da Constituição, é brasileiro nato o nascido no exterior de pai ou mãe brasileira quando qualquer deles está a serviço do Brasil.'),(7,'Correto. O art. 12, I, c, da Constituição prevê nacionalidade brasileira originária ao filho de brasileiro nascido no exterior e registrado em repartição brasileira competente.'),(8,'Correto. O art. 12, I, c, da Constituição permite a opção pela nacionalidade brasileira, após a maioridade, para quem nasceu no exterior de pai ou mãe brasileira e venha residir no Brasil.'),(9,'Correto. O art. 12, II, a, da Constituição prevê para originários de países de língua portuguesa residência por um ano ininterrupto e idoneidade moral, observados os demais requisitos legais.'),(12,'Correto. O art. 12, § 3º, I, da Constituição reserva o cargo de Presidente da República a brasileiro nato.'),(13,'Correto. O art. 12, § 3º, IV, da Constituição exige nacionalidade brasileira nata para o cargo de Ministro do Supremo Tribunal Federal.'),(15,'Correto. O art. 12, § 3º, VI, da Constituição reserva os cargos de oficial das Forças Armadas a brasileiros natos.'),(19,'Correto. O art. 12, § 5º, da Constituição permite readquirir a nacionalidade brasileira originária após renúncia, nos termos da lei.'),(20,'Correto. O art. 13 da Constituição estabelece o português como idioma oficial da República Federativa do Brasil.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.pos=e.ordinality WHERE sm.slug='constitucional-nacionalidade-medidas-retirada' GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;